function ProfilePhoto() {
  const { files, remove } = useFileUpload();
  const photo = files[0];
  return (
    <>
      <Avatar size="xl" source={photo ? { uri: photo.uri } : undefined} fallback="KA" />
      <FileUpload.Trigger>
        <Button variant="secondary">Change photo</Button>
      </FileUpload.Trigger>
      {photo ? <Button variant="ghost" onPress={() => remove(photo.id)}>Remove photo</Button> : null}
    </>
  );
}

<FileUpload
  sources={['camera', 'library']}
  accept={['image/*']}
  image={{ maxWidth: 1024, crop: { aspect: [1, 1] } }}
  upload={uploadFile}
>
